import { createHmac, randomBytes, timingSafeEqual } from "node:crypto";
import { SignJWT, jwtVerify } from "jose";

/**
 * Staff-only workspace gateway — the PURE half (no DB, no next/headers).
 *
 * WHY A GATEWAY TOKEN AND NOT THE SESSION COOKIE
 * ----------------------------------------------
 * The main site's session cookie (`nxeon_session`, lib/auth.ts) is HOST-ONLY: it
 * is set with no `Domain` attribute, so the browser only sends it to nxeon.cloud.
 * The workspace lives on a DIFFERENT registrable domain (workspace.trynxeon.com),
 * so nginx's `auth_request` can never see that cookie there, and we deliberately
 * do NOT widen the cookie domain (that would hand the session to every host under
 * the domain, and trynxeon.com is the cold-email sending domain besides).
 *
 * Instead: a small login hop. The workspace host bounces an unauthenticated
 * browser to nxeon.cloud, where the real session is checked; a 60-second,
 * single-use, signed GRANT is handed back to the workspace host, which swaps it
 * for a host-only gateway cookie. Four signed artefacts, all HS256 under a key
 * derived from AUTH_SECRET with a purpose label (so none can be replayed as a
 * session token or as each other — each also carries its own `typ` + `aud`):
 *
 *   ws-state  start -> login     carries the sanitised `next` path + browser nonce
 *   ws-grant  login -> callback  carries the verified identity, 60s, single-use
 *   ws-gw     the workspace cookie, `WORKSPACE_TTL_HOURS` (default 8h)
 *   (sig)     HMAC over the identity headers so the upstream can verify them
 *
 * The gateway cookie is stateless, so every `auth_request` re-checks the user
 * against the database (still allowed, not suspended, sessionVersion unchanged,
 * originating session not revoked). Revocation is therefore immediate even though
 * the cookie itself lasts hours.
 */

export const WORKSPACE_STATE_TTL_S = 10 * 60;
export const WORKSPACE_GRANT_TTL_S = 60;
const DEFAULT_TTL_HOURS = 8;
const MAX_TTL_HOURS = 24;
/** Allowed clock skew when verifying signed identity headers upstream. */
export const UPSTREAM_SIG_SKEW_S = 5 * 60;

export type WsRole = "ADMIN" | "SUPPORT" | "BILLING" | "EMPLOYEE" | "CUSTOMER";

export type WorkspaceConfig = {
  /** https://workspace.trynxeon.com (no trailing slash). */
  workspaceOrigin: string;
  /** https://nxeon.cloud (no trailing slash). */
  mainOrigin: string;
  /** Roles allowed in. Default SUPPORT,BILLING,ADMIN (== isStaff in lib/rbac.ts). */
  allowedRoles: WsRole[];
  require2fa: boolean;
  ttlHours: number;
  /** HS256 key for all gateway tokens. */
  key: Uint8Array;
  /** Shared secret with the upstream for the identity-header signature, if set. */
  upstreamSecret: string | null;
};

const ROLES: WsRole[] = ["ADMIN", "SUPPORT", "BILLING", "EMPLOYEE", "CUSTOMER"];

function stripSlash(s: string): string {
  return s.replace(/\/+$/, "");
}

/** Domain-separated key: never the raw AUTH_SECRET, so these tokens cannot verify as sessions. */
export function deriveKey(authSecret: string): Uint8Array {
  return new Uint8Array(createHmac("sha256", authSecret).update("nxeon:workspace-gateway:v1").digest());
}

export function parseRoles(raw: string | undefined | null): WsRole[] {
  const out = (raw ?? "")
    .split(",")
    .map((s) => s.trim().toUpperCase())
    .filter((s): s is WsRole => (ROLES as string[]).includes(s))
    // A customer account must never be allowed in, whatever the env says.
    .filter((s) => s !== "CUSTOMER");
  return out.length ? [...new Set(out)] : ["SUPPORT", "BILLING", "ADMIN"];
}

export function loadConfig(env: Record<string, string | undefined> = process.env): WorkspaceConfig | null {
  const authSecret = env.AUTH_SECRET;
  if (!authSecret) return null;
  const ttl = Number(env.WORKSPACE_TTL_HOURS);
  return {
    workspaceOrigin: stripSlash(env.WORKSPACE_ORIGIN || "https://workspace.trynxeon.com"),
    mainOrigin: stripSlash(env.APP_URL || "https://nxeon.cloud"),
    allowedRoles: parseRoles(env.WORKSPACE_ROLES),
    require2fa: env.WORKSPACE_REQUIRE_2FA === "1",
    ttlHours: Number.isFinite(ttl) && ttl > 0 ? Math.min(ttl, MAX_TTL_HOURS) : DEFAULT_TTL_HOURS,
    key: deriveKey(authSecret),
    upstreamSecret: env.WORKSPACE_UPSTREAM_SECRET?.trim() || null,
  };
}

// ---------------------------------------------------------------------------
// Open-redirect protection
// ---------------------------------------------------------------------------

/**
 * Reduce an untrusted `next` to a same-origin PATH, or null. The redirect target
 * is always `workspaceOrigin + path`, so the host can never be influenced; this
 * additionally refuses anything a browser or proxy might reinterpret
 * (protocol-relative, backslashes, control chars, encoded newlines) and anything
 * under the gateway's own `/_nx/` namespace (a login loop).
 */
export function sanitizeNext(raw: unknown): string | null {
  if (typeof raw !== "string") return null;
  const s = raw.trim();
  if (!s || s.length > 512) return null;
  if (!s.startsWith("/")) return null;
  if (s.startsWith("//") || s.includes("\\")) return null;
  if (/[\x00-\x1f\x7f]/.test(s)) return null;
  if (/%(?:0[0-9a-f]|1[0-9a-f]|7f|5c)/i.test(s)) return null; // encoded control chars / backslash
  if (s === "/_nx" || s.startsWith("/_nx/") || s.startsWith("/_nx?")) return null;
  try {
    const u = new URL(s, "https://workspace.invalid");
    if (u.origin !== "https://workspace.invalid") return null;
  } catch {
    return null;
  }
  return s;
}

/** Where a signed-in browser lands after the hop: the sanitised path, else "/". */
export function landingPath(raw: unknown): string {
  return sanitizeNext(raw) ?? "/";
}

