// Token minting / verification
// ---------------------------------------------------------------------------

type Typ = "ws-state" | "ws-grant" | "ws-gw";

const AUD: Record<Typ, string> = {
  "ws-state": "nxeon-workspace:state",
  "ws-grant": "nxeon-workspace:grant",
  "ws-gw": "nxeon-workspace:gateway",
};

async function mint(cfg: Pick<WorkspaceConfig, "key">, typ: Typ, claims: Record<string, unknown>, ttlS: number, nowS: number) {
  return new SignJWT({ ...claims, typ })
    .setProtectedHeader({ alg: "HS256" })
    .setAudience(AUD[typ])
    .setIssuer("nxeon-workspace")
    .setIssuedAt(nowS)
    .setExpirationTime(nowS + ttlS)
    .sign(cfg.key);
}

async function verify(cfg: Pick<WorkspaceConfig, "key">, typ: Typ, token: unknown, nowS: number) {
  if (typeof token !== "string" || token.length < 20 || token.length > 4096) return null;
  try {
    const { payload } = await jwtVerify(token, cfg.key, {
      algorithms: ["HS256"],
      audience: AUD[typ],
      issuer: "nxeon-workspace",
      currentDate: new Date(nowS * 1000),
    });
    return payload.typ === typ ? payload : null;
  } catch {
    return null;
