import { headers } from "next/headers";
import { db } from "./db";
import { getSetting, getSettingBool } from "./settings";
import { staffIpBlocked } from "./staff-ip";
import { loadConfig, type UserRow, type WorkspaceConfig } from "./workspace-gateway";

/**
 * Server-side glue for the workspace gateway routes under app/api/workspace/*.
 * The decision logic lives in lib/workspace-gateway.ts (pure, tested); this file
 * only adapts it to Prisma, settings and request headers.
 */

export function config(): WorkspaceConfig | null {
  return loadConfig();
}

export async function loadUser(id: string): Promise<UserRow | null> {
  return db.user.findUnique({
    where: { id },
    select: { id: true, email: true, role: true, suspended: true, sessionVersion: true, totpEnabled: true },
  });
}

/** Same semantics as realUser(): no tracked row is valid; a revoked row is not. */
export async function loadSession(sid: string): Promise<{ revoked: boolean } | null> {
  const row = await db.userSession.findUnique({ where: { tokenHash: sid }, select: { revokedAt: true } });
  return row ? { revoked: row.revokedAt !== null } : null;
}

/** Honour the admin portal's own `enforce_staff_2fa` switch. */
export async function enforceStaff2fa(): Promise<boolean> {
  return getSettingBool("enforce_staff_2fa", false);
}

