import { NextRequest, NextResponse } from "next/server";
import {
  cookieNames,
  decideGatewayAuth,
  loginLocation,
  upstreamHeaders,
  wantsLoginRedirect,
} from "@/lib/workspace-gateway";
import { config, enforceStaff2fa, loadSession, loadUser } from "@/lib/workspace-gateway-server";

