 *        copies onto the upstream request (overwriting any client-supplied copies)
 *   401  not signed in; X-Nx-Login-Location is set only for top-level navigations
 *   403  signed in but not (or no longer) allowed
 *
 * Reads ONLY the workspace gateway cookie — never the main-site session cookie,
 * which is host-only and never reaches this host. Never cached. Fails CLOSED:
 * missing AUTH_SECRET, a DB error or anything unexpected is a 401/500, never a 200.
 */
export const dynamic = "force-dynamic";

const NO_STORE = { "cache-control": "no-store" };

export async function GET(req: NextRequest) {
  const cfg = config();
  if (!cfg) return new NextResponse(null, { status: 500, headers: NO_STORE });
  try {
    const secure = process.env.NODE_ENV === "production";
    const token = req.cookies.get(cookieNames(secure).gw)?.value;
    const d = await decideGatewayAuth({
      cfg,
      token,
      enforceStaff2fa: token ? await enforceStaff2fa() : false,
      loadUser,
      loadSession,
    });
    if (d.status === 200) {
      return new NextResponse(null, { status: 200, headers: { ...NO_STORE, ...upstreamHeaders(cfg, d.identity) } });
    }
    if (d.status === 403) return new NextResponse(null, { status: 403, headers: { ...NO_STORE, "x-nx-deny": d.reason } });
    const headers: Record<string, string> = { ...NO_STORE, "x-nx-deny": d.reason };
    if (
      wantsLoginRedirect({
        method: req.headers.get("x-original-method"),
        secFetchMode: req.headers.get("x-nx-fetch-mode"),
        upgrade: req.headers.get("x-nx-upgrade"),
        accept: req.headers.get("x-nx-accept"),
      })
    ) {
      headers["x-nx-login-location"] = loginLocation(cfg, req.headers.get("x-original-uri"));
