import { NextRequest, NextResponse } from "next/server";
import { currentSessionTokenHash, impersonating, realUser } from "@/lib/auth";
import { evaluateUser, mintGrant, verifyState } from "@/lib/workspace-gateway";
import { randomUUID } from "node:crypto";
import { config, enforceStaff2fa, esc, hopIpBlocked, htmlPage } from "@/lib/workspace-gateway-server";

/**
 * Step 2 of the login hop — runs on the MAIN site (nxeon.cloud), where the real
 * host-only session cookie is visible. Verifies the signed state, then the
 * account, then hands a 60s single-use grant to the workspace host.
 *
 * Refused here (never reaches the workspace): signed-out (sent to /login and
 * back), impersonated sessions, customers, suspended accounts, accounts outside
 * the admin IP allow-list, and staff without 2FA when 2FA is enforced.
 */
export const dynamic = "force-dynamic";

const deny = (title: string, msg: string, status = 403) =>
  htmlPage(status, title, `<h1>${esc(title)}</h1><p>${esc(msg)}</p>`);

export async function GET(req: NextRequest) {
  const cfg = config();
  if (!cfg) return deny("Workspace unavailable", "The gateway is not configured.", 500);

  const sRaw = req.nextUrl.searchParams.get("s");
  const state = await verifyState(cfg, sRaw);
  if (!state) return deny("Link expired", "This sign-in link is invalid or has expired. Open the workspace again to restart.", 400);

  const user = await realUser();
  if (!user) {
    // Round-trip through the normal login (which validates `next` with safeNext).
    const back = `/api/workspace/login?s=${encodeURIComponent(String(sRaw))}`;
    return NextResponse.redirect(`${cfg.mainOrigin}/login?next=${encodeURIComponent(back)}`, 303);
  }
  if (await impersonating()) {
    return deny("Stop impersonating first", "The workspace is not available while impersonating a customer. Exit impersonation and try again.");
  }
  const v = evaluateUser(
    { id: user.id, email: user.email, role: user.role, suspended: user.suspended, sessionVersion: user.sessionVersion, totpEnabled: user.totpEnabled },
    cfg,
    { enforceStaff2fa: await enforceStaff2fa() },
  );
  if (!v.ok) {
    if (v.reason === "2fa") return deny("Two-factor required", "Turn on two-factor authentication in your account settings, then reopen the workspace.");
    return deny("No access", "This account does not have access to the Nxeon workspace.");
  }
  if (await hopIpBlocked(user)) return deny("Network not allowed", "Your current network is not on the staff allow-list.");

  const sid = await currentSessionTokenHash();
  if (!sid) return deny("Sign in again", "Your session could not be verified.", 401);

  const grant = await mintGrant(
    cfg,
    { uid: user.id, email: user.email, role: user.role, sv: user.sessionVersion ?? 0, sid },
    state.next,
    state.nonce,
    randomUUID(),
  );
  const res = NextResponse.redirect(`${cfg.workspaceOrigin}/_nx/callback?g=${encodeURIComponent(grant)}`, 303);
  res.headers.set("cache-control", "no-store");
  res.headers.set("referrer-policy", "no-referrer");
  return res;
}
