import { timingSafeEqual } from "node:crypto";
import { NextRequest, NextResponse } from "next/server";
import { claimOnce } from "@/lib/rate-limit";
import { cookieNames, decideGatewayAuth, mintGateway, verifyGrant } from "@/lib/workspace-gateway";
import { config, enforceStaff2fa, esc, htmlPage, loadSession, loadUser } from "@/lib/workspace-gateway-server";

/**
 * Step 3 of the login hop (reached as workspace.trynxeon.com/_nx/callback; nginx
 * does NOT run auth_request here). Swaps the grant for the host-only gateway
 * cookie. Checks, in order: grant signature/expiry/audience, single use, the
 * nonce cookie planted by /start (same browser), then re-evaluates the account.
 */
export const dynamic = "force-dynamic";

const fail = (msg: string, status = 400) =>
  htmlPage(status, "Sign-in failed", `<h1>Sign-in failed</h1><p>${esc(msg)}</p><a href="/_nx/start?next=%2F">Try again</a>`);

function sameNonce(a: string, b: string): boolean {
  const x = Buffer.from(a);
  const y = Buffer.from(b);
  return x.length === y.length && timingSafeEqual(x, y);
}

export async function GET(req: NextRequest) {
  const cfg = config();
  if (!cfg) return fail("The gateway is not configured.", 500);
  const secure = process.env.NODE_ENV === "production";
  const names = cookieNames(secure);

  const grant = await verifyGrant(cfg, req.nextUrl.searchParams.get("g"));
  if (!grant) return fail("This sign-in link is invalid or has expired.");
  const nonceCookie = req.cookies.get(names.st)?.value;
  if (!nonceCookie || !sameNonce(nonceCookie, grant.nonce)) {
    return fail("This sign-in was not started in this browser. Open the workspace directly and sign in again.");
  }
  if (!claimOnce(`wsgrant:${grant.jti}`, 5 * 60_000)) return fail("This sign-in link was already used.");

  // Re-use the per-request decision so the callback can never mint a cookie the
  // auth endpoint would then refuse.
  const probe = await mintGateway(cfg, grant.identity);
  const d = await decideGatewayAuth({ cfg, token: probe, enforceStaff2fa: await enforceStaff2fa(), loadUser, loadSession });
  if (d.status !== 200) return fail("This account does not have access to the workspace.", 403);

  const res = NextResponse.redirect(`${cfg.workspaceOrigin}${grant.next}`, 303);
  res.cookies.set(names.gw, probe, {
    httpOnly: true,
    secure,
    sameSite: "lax",
    path: "/",
    maxAge: Math.round(cfg.ttlHours * 3600),
  });
  res.cookies.delete(names.st);
  res.headers.set("cache-control", "no-store");
  res.headers.set("referrer-policy", "no-referrer");
  return res;
}
