import { NextRequest, NextResponse } from "next/server";
import { cookieNames } from "@/lib/workspace-gateway";
import { config, htmlPage } from "@/lib/workspace-gateway-server";

/**
 * workspace.trynxeon.com/_nx/logout. Clears the gateway cookie. POST only does
 * the work (GET just shows a confirm button) so a third-party page cannot sign
 * staff out with an <img>; the POST must come from the workspace origin itself.
 * This does NOT end the nxeon.cloud session. To revoke everywhere, revoke the
 * session in Settings (the gateway re-checks it on every request) or bump the
 * account's sessionVersion.
 */
export const dynamic = "force-dynamic";

export async function GET() {
  return htmlPage(200, "Sign out", `<h1>Sign out of the workspace?</h1><form method="post" action="/_nx/logout"><button type="submit">Sign out</button></form>`);
}

export async function POST(req: NextRequest) {
  const cfg = config();
  if (!cfg) return htmlPage(500, "Workspace unavailable", "<h1>Workspace unavailable</h1>");
  const origin = req.headers.get("origin");
  if (origin !== cfg.workspaceOrigin) return htmlPage(403, "Refused", "<h1>Refused</h1><p>Cross-site sign-out is not allowed.</p>");
  const secure = process.env.NODE_ENV === "production";
  const res = new NextResponse(
    (await htmlPage(200, "Signed out", `<h1>Signed out</h1><p>You are signed out of the workspace.</p><a href="/">Sign in again</a>`)).body,
    { status: 200, headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" } },
  );
  res.cookies.set(cookieNames(secure).gw, "", { httpOnly: true, secure, sameSite: "lax", path: "/", maxAge: 0 });
  return res;
}
