"use strict";
// Nxeon workspace — reference upstream. Zero dependencies, Node >= 18.
//
// It does exactly three things: trusts ONLY the gateway's signed identity
// headers, shows who is signed in, and answers /healthz. The real workspace UI
// is built on top of this (see README.md and CLAUDE.md).
const http = require("node:http");
const { identityFromHeaders } = require("./identity.js");

const HOST = process.env.BIND_HOST || "127.0.0.1";
const PORT = Number(process.env.PORT || 3000);
const SECRET = (process.env.WORKSPACE_UPSTREAM_SECRET || "").trim();
const LOOPBACK = new Set(["127.0.0.1", "::1", "localhost"]);

if (!SECRET) {
  console.error("WORKSPACE_UPSTREAM_SECRET is not set: refusing to start (identity headers could not be verified).");
  process.exit(1);
}
if (HOST === "0.0.0.0" || HOST === "::") {
  console.error(
    "BIND_HOST=" + HOST + " listens on every interface. Bind the VM's private address (e.g. 10.20.3.112) and rely on the VM firewall; refusing to start.",
  );
  process.exit(1);
}
if (!LOOPBACK.has(HOST) && process.env.I_UNDERSTAND_GATEWAY_ONLY !== "1") {
  console.error("Non-loopback BIND_HOST requires I_UNDERSTAND_GATEWAY_ONLY=1 (and the VM firewall rule from the runbook). Refusing to start.");
  process.exit(1);
}

const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);

const SEC_HEADERS = {
  "cache-control": "no-store",
  "x-content-type-options": "nosniff",
  "referrer-policy": "same-origin",
  "x-frame-options": "DENY",
  "content-security-policy": "default-src 'self'; style-src 'unsafe-inline'; frame-ancestors 'none'; base-uri 'none'",
};

function handler(req, res) {
  const path = (req.url || "/").split("?")[0];

  if (path === "/healthz") {
    res.writeHead(200, { ...SEC_HEADERS, "content-type": "application/json" });
    return res.end(JSON.stringify({ ok: true, service: "nxeon-workspace" }));
  }

  const who = identityFromHeaders(req.headers, SECRET);
  if (!who) {
    // Fail closed. A request that did not come through the gateway (or whose
    // headers were forged/stale) is anonymous, and this app has nothing for
    // anonymous callers.
    res.writeHead(401, { ...SEC_HEADERS, "content-type": "text/plain; charset=utf-8" });
    return res.end("Unauthorized: open this app through the Nxeon workspace gateway.\n");
  }

  if (path === "/api/whoami") {
    res.writeHead(200, { ...SEC_HEADERS, "content-type": "application/json" });
    return res.end(JSON.stringify(who));
  }

  if (path === "/") {
    res.writeHead(200, { ...SEC_HEADERS, "content-type": "text/html; charset=utf-8" });
    return res.end(
      `<!doctype html><meta charset="utf-8"><title>Nxeon workspace</title>` +
        `<body style="font:16px system-ui;background:#0a1020;color:#e6e9f5;padding:2rem">` +
        `<h1>Nxeon workspace</h1><p>Signed in as <b>${esc(who.email)}</b> (${esc(who.role)}).</p>` +
        `<p>Reference upstream: replace this page with the real UI.</p>` +
        `<form method="post" action="/_nx/logout"><button>Sign out</button></form></body>`,
    );
  }

  res.writeHead(404, { ...SEC_HEADERS, "content-type": "text/plain; charset=utf-8" });
  res.end("Not found\n");
}

if (require.main === module) {
  http.createServer(handler).listen(PORT, HOST, () => console.log(`nxeon-workspace listening on ${HOST}:${PORT}`));
}

module.exports = { handler };
