cd /tank/nxeon-wt-workspace/deploy && cat > workspace-gateway.http.conf.template <<'EOF'
# /etc/nginx/conf.d/nxeon-workspace.conf   (http{} context; rendered by
# scripts/workspace-gateway-install.sh — do not hand-edit the installed copy)
#
# Everything the workspace vhost needs at http level: rate-limit zones, the
# "did this connection really come from Cloudflare" map, and the cookie filter.

# Per-client request budget for the proxied app, and a much tighter one for the
# three login-hop endpoints (/_nx/start, /_nx/callback, /_nx/logout).
limit_req_zone $binary_remote_addr zone=nxws_app:10m rate=40r/s;
limit_req_zone $binary_remote_addr zone=nxws_hop:10m rate=5r/s;
limit_req_status 429;

# 1 only when the TCP peer is a Cloudflare edge address (or always 1 in DNS-only
# mode). Evaluated on $realip_remote_addr, i.e. the real peer, BEFORE the
# CF-Connecting-IP rewrite — so a direct hit on the origin with a forged
# CF-Connecting-IP header is still refused.
geo $realip_remote_addr $nxws_from_cf {
    default @@GEO_DEFAULT@@;
@@GEO_RANGES@@
}

# The gateway's own cookies must never reach the upstream app (it is an AI
# sandbox; a leaked gateway JWT is a staff login for hours). Strip them from the
# Cookie header we forward; the app's own cookies pass through untouched.
map $http_cookie $nxws_cookie_upstream {
    default $http_cookie;
    "~^(.*?)(?:^|;\s*)(?:__Host-nxws|nxws)(?:_st)?=[^;]*(.*)$" "$1$2";
}
EOF
cat > workspace.trynxeon.com.nginx.conf <<'EOF'
# /etc/nginx/sites-available/workspace-trynxeon   (rendered by
# scripts/workspace-gateway-install.sh; symlinked into sites-enabled)
#
# Staff-only front door for the project-management VM's workspace app.
#
#   browser -> Cloudflare (proxied) -> THIS vhost on the primary (TLS, auth_request)
#           -> node-4 public IP @@UPSTREAM@@ (DNAT to the VM's :3000, source-locked
#              to the primary by node-4's firewall) -> the app
#
# Identity for the upstream is produced ONLY by the auth subrequest below and set
# with proxy_set_header, which overwrites any client-supplied copy.

server {
    listen 80;
    listen [::]:80;
    server_name @@WS_HOST@@;
    location ^~ /.well-known/acme-challenge/ { root /var/www/certbot; }
    location / { return 301 https://$host$request_uri; }
}

server {
    listen 443 ssl;
    listen [::]:443 ssl;
    http2 on;
    server_name @@WS_HOST@@;

    ssl_certificate     /etc/letsencrypt/live/@@WS_HOST@@/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/@@WS_HOST@@/privkey.pem;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers HIGH:!aNULL:!MD5;

    # Real client address from Cloudflare (no-op file in DNS-only mode).
    include /etc/nginx/snippets/nxeon-workspace-cf-realip.conf;

    server_tokens off;
    client_max_body_size 50m;
    client_body_timeout 60s;
    client_header_timeout 20s;
    large_client_header_buffers 4 16k;

    # Security headers. Declared once, at server level, with no add_header inside
    # any location (a location-level add_header would silently drop all of these).
    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains" always;
    add_header X-Content-Type-Options "nosniff" always;
    add_header X-Frame-Options "DENY" always;
    add_header Referrer-Policy "same-origin" always;
    add_header Permissions-Policy "camera=(), microphone=(), geolocation=(), payment=()" always;
    add_header Content-Security-Policy "frame-ancestors 'none'" always;
    add_header X-Robots-Tag "noindex, nofollow, noarchive" always;
    add_header Cross-Origin-Opener-Policy "same-origin" always;

