cd /tank/nxeon-wt-workspace && cat > test/workspace-gateway.test.ts <<'EOF'
import { test } from "node:test";
import assert from "node:assert/strict";
import { createRequire } from "node:module";
import { readFileSync } from "node:fs";
import { SignJWT } from "jose";
import {
  cookieNames,
  decideGatewayAuth,
  deriveKey,
  evaluateUser,
  headerSafe,
  loadConfig,
  loginLocation,
  mintGateway,
  mintGrant,
  mintState,
  parseRoles,
  sanitizeNext,
  upstreamHeaders,
  verifyGateway,
  verifyGrant,
  verifyState,
  verifyUpstreamHeaders,
  wantsLoginRedirect,
  type Identity,
  type UserRow,
  type WorkspaceConfig,
} from "../lib/workspace-gateway.ts";

/**
 * The workspace gateway decision logic (lib/workspace-gateway.ts): who gets a
 * 200 from the nginx auth_request endpoint, what a login redirect may point at,
 * and whether the identity headers handed to the upstream can be forged.
 * The route handlers are thin adapters over these functions.
 */

const NOW = 1_800_000_000;
const AUTH_SECRET = "test-auth-secret-0123456789abcdef0123456789abcdef";
const UPSTREAM_SECRET = "upstream-secret-0123456789abcdef0123456789abcdef";

const cfg = loadConfig({ AUTH_SECRET, WORKSPACE_UPSTREAM_SECRET: UPSTREAM_SECRET })!;

const staff: UserRow = { id: "u_staff", email: "ops@nxeon.cloud", role: "ADMIN", suspended: false, sessionVersion: 0, totpEnabled: true };
const idOf = (u: UserRow, sid = "sid1"): Identity => ({ uid: u.id, email: u.email, role: u.role as Identity["role"], sv: u.sessionVersion ?? 0, sid });

const users: Record<string, UserRow> = {
  u_staff: staff,
  u_support: { ...staff, id: "u_support", role: "SUPPORT" },
  u_billing: { ...staff, id: "u_billing", role: "BILLING" },
  u_employee: { ...staff, id: "u_employee", role: "EMPLOYEE" },
  u_customer: { ...staff, id: "u_customer", role: "CUSTOMER", email: "c@example.com" },
  u_susp: { ...staff, id: "u_susp", suspended: true },
  u_no2fa: { ...staff, id: "u_no2fa", totpEnabled: false },
};

async function decide(token: string | undefined, over: Partial<Parameters<typeof decideGatewayAuth>[0]> = {}, db = users, revoked = new Set<string>()) {
  return decideGatewayAuth({
    cfg,
    token,
    nowS: NOW,
    loadUser: async (id) => db[id] ?? null,
    loadSession: async (sid) => (revoked.has(sid) ? { revoked: true } : null),
    ...over,
  });
}

// ---- who is allowed in ------------------------------------------------------

test("staff roles pass, customers never do", async () => {
  for (const id of ["u_staff", "u_support", "u_billing"]) {
    const t = await mintGateway(cfg, idOf(users[id]), NOW);
    const d = await decide(t);
    assert.equal(d.status, 200, id);
  }
  const t = await mintGateway(cfg, idOf(users.u_customer), NOW);
  const d = await decide(t);
  assert.deepEqual([d.status, (d as { reason?: string }).reason], [403, "role"]);
});

test("EMPLOYEE is excluded by default and only admitted when WORKSPACE_ROLES says so", async () => {
  const t = await mintGateway(cfg, idOf(users.u_employee), NOW);
  assert.equal((await decide(t)).status, 403);
  const cfg2 = loadConfig({ AUTH_SECRET, WORKSPACE_ROLES: "ADMIN,EMPLOYEE" })!;
  const t2 = await mintGateway(cfg2, idOf(users.u_employee), NOW);
  assert.equal((await decide(t2, { cfg: cfg2 })).status, 200);
  // ...and the env can never admit a CUSTOMER.
  assert.deepEqual(parseRoles("CUSTOMER,ADMIN"), ["ADMIN"]);
  assert.deepEqual(parseRoles("CUSTOMER"), ["SUPPORT", "BILLING", "ADMIN"]);
  assert.equal(evaluateUser(users.u_customer, { allowedRoles: ["CUSTOMER" as never], require2fa: false }).ok, false);
});

test("a suspended account is refused even with a perfectly valid token", async () => {
  const t = await mintGateway(cfg, idOf(users.u_susp), NOW);
  const d = await decide(t);
  assert.deepEqual([d.status, (d as { reason?: string }).reason], [403, "suspended"]);
});

test("2FA: honoured when enforce_staff_2fa is on or WORKSPACE_REQUIRE_2FA=1", async () => {
  const t = await mintGateway(cfg, idOf(users.u_no2fa), NOW);
  assert.equal((await decide(t)).status, 200, "off by default, like the admin portal");
  assert.deepEqual([(await decide(t, { enforceStaff2fa: true })).status], [403]);
  const strict = loadConfig({ AUTH_SECRET, WORKSPACE_REQUIRE_2FA: "1" })!;
  const ts = await mintGateway(strict, idOf(users.u_no2fa), NOW);
  assert.equal((await decide(ts, { cfg: strict })).status, 403);
  const tOk = await mintGateway(strict, idOf(users.u_staff), NOW);
  assert.equal((await decide(tOk, { cfg: strict })).status, 200);
});

// ---- unauthenticated / invalid / expired / revoked -------------------------

test("no token, garbage, wrong-key, wrong-type and expired tokens are all 401", async () => {
  assert.equal((await decide(undefined)).status, 401);
  assert.equal((await decide("")).status, 401);
  assert.equal((await decide("not.a.jwt")).status, 401);

  const good = await mintGateway(cfg, idOf(staff), NOW);
  // One flipped signature character.
  assert.equal((await decide(good.slice(0, -2) + (good.endsWith("AA") ? "BB" : "AA"))).status, 401);

  const other = loadConfig({ AUTH_SECRET: AUTH_SECRET + "x" })!;
  assert.equal((await decide(await mintGateway(other, idOf(staff), NOW))).status, 401, "different secret");

  // A grant or state token must never work as a gateway cookie.
  const grant = await mintGrant(cfg, idOf(staff), "/", "n", "j", NOW);
  const state = await mintState(cfg, "/", "n", NOW);
  assert.equal((await decide(grant)).status, 401);
  assert.equal((await decide(state)).status, 401);

  // Expired: just past the TTL, and the same token is fine just before it.
  const ttl = cfg.ttlHours * 3600;
  assert.equal((await decide(good, { nowS: NOW + ttl - 5 })).status, 200);
  const late = await decide(good, { nowS: NOW + ttl + 5 });
  assert.deepEqual([late.status, (late as { reason?: string }).reason], [401, "bad-token"]);
});

test("a main-site SESSION token (same AUTH_SECRET, HS256) is not a gateway token", async () => {
  const raw = new TextEncoder().encode(AUTH_SECRET);
  const session = await new SignJWT({ sub: staff.id, sv: 0, typ: "session" })
    .setProtectedHeader({ alg: "HS256" }).setIssuedAt(NOW).setExpirationTime(NOW + 3600).sign(raw);
  assert.equal((await decide(session)).status, 401);
  // ...and the derived key is not the raw secret.
  assert.notDeepEqual(Buffer.from(deriveKey(AUTH_SECRET)), Buffer.from(raw));
});

test("alg=none and algorithm-confusion tokens are rejected", async () => {
  const b64 = (o: object) => Buffer.from(JSON.stringify(o)).toString("base64url");
  const none = `${b64({ alg: "none", typ: "JWT" })}.${b64({ sub: staff.id, sv: 0, sid: "s", typ: "ws-gw", aud: "nxeon-workspace:gateway", iss: "nxeon-workspace", exp: NOW + 999 })}.`;
