test("without an upstream secret the gateway sends no signature (starter then refuses everyone)", () => {
  const noSecret = loadConfig({ AUTH_SECRET })!;
  assert.equal("x-nxeon-sig" in upstreamHeaders(noSecret, idOf(staff), NOW), false);
});

test("header values cannot smuggle CR/LF or non-ASCII", () => {
  assert.equal(headerSafe("a@b.c\r\nX-Nxeon-Role: ADMIN"), "a@b.cX-Nxeon-Role: ADMIN");
  assert.equal(/[\r\n]/.test(upstreamHeaders(cfg, { ...idOf(staff), email: "x\r\ny@z" })["x-nxeon-email"]), false);
});

test("the starter app's verifier agrees with the gateway's signer, and fails closed", () => {
  const require = createRequire(import.meta.url);
  const { identityFromHeaders } = require("../workspace-app-starter/identity.js");
  const h = upstreamHeaders(cfg, idOf(staff), NOW);
  assert.deepEqual(identityFromHeaders(h, UPSTREAM_SECRET, NOW), { uid: staff.id, email: staff.email, role: "ADMIN" });
  assert.equal(identityFromHeaders({ ...h, "x-nxeon-role": "SUPPORT" }, UPSTREAM_SECRET, NOW), null);
  assert.equal(identityFromHeaders(h, "", NOW), null, "no secret configured => nobody is signed in");
  assert.equal(identityFromHeaders({ "x-nxeon-user": "u", "x-nxeon-email": "e", "x-nxeon-role": "ADMIN" }, UPSTREAM_SECRET, NOW), null, "unsigned spoof");
});

// ---- configuration + cookie scope ------------------------------------------

test("config: refuses to exist without AUTH_SECRET; TTL is clamped; defaults point at the right origins", () => {
  assert.equal(loadConfig({}), null);
  assert.equal(loadConfig({ AUTH_SECRET, WORKSPACE_TTL_HOURS: "9999" })!.ttlHours, 24);
  assert.equal(loadConfig({ AUTH_SECRET, WORKSPACE_TTL_HOURS: "nope" })!.ttlHours, 8);
  const c: WorkspaceConfig = loadConfig({ AUTH_SECRET })!;
  assert.equal(c.workspaceOrigin, "https://workspace.trynxeon.com");
  assert.equal(c.mainOrigin, "https://nxeon.cloud");
});

test("gateway cookies are host-only __Host- cookies in production; the session cookie is never widened", () => {
  assert.deepEqual(cookieNames(true), { gw: "__Host-nxws", st: "__Host-nxws_st" });
  // lib/auth.ts must keep setting the session cookie WITHOUT a Domain attribute.
  const auth = readFileSync(new URL("../lib/auth.ts", import.meta.url), "utf8");
  assert.equal(/\bdomain\s*:/i.test(auth), false, "lib/auth.ts must not set a cookie Domain");
  // ...and the gateway routes never set one either.
  for (const f of ["start", "callback", "logout"]) {
    const src = readFileSync(new URL(`../app/api/workspace/${f}/route.ts`, import.meta.url), "utf8");
    assert.equal(/\bdomain\s*:/i.test(src.replace(/\/\*[\s\S]*?\*\//g, "").replace(/\/\/.*$/gm, "")), false, f);
  }
});

test("the auth route reads only the gateway cookie, never the main session cookie", () => {
  const src = readFileSync(new URL("../app/api/workspace/auth/route.ts", import.meta.url), "utf8");
  assert.match(src, /cookieNames\(secure\)\.gw/);
  assert.equal(/nxeon_session|realUser|currentUser/.test(src.replace(/\/\*[\s\S]*?\*\//g, "")), false);
});

test("the login hop refuses impersonated sessions", () => {
  const src = readFileSync(new URL("../app/api/workspace/login/route.ts", import.meta.url), "utf8");
  assert.match(src, /await impersonating\(\)/);
});
