/**
 * Add the ONE DNS record the staff workspace needs, on the trynxeon.com
 * Cloudflare zone:
 *
 *     workspace.trynxeon.com   A   51.79.162.96   (the primary)
 *
 * trynxeon.com is also the cold-email sending domain (MX/SPF/DKIM/DMARC live in
 * this zone), so this script is deliberately incapable of anything but that one
 * record: it only ever calls
 *   - GET  zones?name=trynxeon.com
 *   - GET  zones/<id>/dns_records?name=workspace.trynxeon.com      (read-only lookup)
 *   - POST zones/<id>/dns_records           (type A, name workspace, --apply only)
 *   - PUT  zones/<id>/dns_records/<id>      (--set-proxied only, on that same A record)
 * and it REFUSES to create anything if ANY record of ANY type already exists
 * for the host.
 *
 * Usage (from /opt/nxeon, with a token in the environment — never on the command line):
 *   CF_TRYNXEON_TOKEN=... npx tsx scripts/workspace-dns-add.ts                  # dry run (default)
 *   CF_TRYNXEON_TOKEN=... npx tsx scripts/workspace-dns-add.ts --apply          # create, DNS-only (grey cloud)
 *   CF_TRYNXEON_TOKEN=... npx tsx scripts/workspace-dns-add.ts --apply --proxied
 *   CF_TRYNXEON_TOKEN=... npx tsx scripts/workspace-dns-add.ts --set-proxied=true  [--apply]
 *
 * The token must be Zone:Read + DNS:Edit on trynxeon.com. NOTE: the platform's
 * CLOUDFLARE_DNS_API_TOKEN (.env) is scoped to nxeon.cloud only (verified
 * 2026-10-02: it cannot see the trynxeon.com zone) and is intentionally NOT used.
 */
import { cfFindZoneId, cfRequest, cfVerifyToken } from "../lib/cloudflare-dns";

const ZONE = "trynxeon.com";
const LABEL = "workspace";
const HOST = `${LABEL}.${ZONE}`;
const ORIGIN_IP = process.env.WS_ORIGIN_IP ?? "51.79.162.96";
const COMMENT = "Nxeon staff workspace gateway (nginx on the primary) - added by scripts/workspace-dns-add.ts";

type Rec = { id: string; type: string; name: string; content: string; proxied?: boolean; ttl: number };

const args = process.argv.slice(2);
const apply = args.includes("--apply");
const proxied = args.includes("--proxied");
const setProxied = args.find((a) => a.startsWith("--set-proxied="))?.split("=")[1];

async function main() {
  const token = (process.env.CF_TRYNXEON_TOKEN ?? "").trim();
  if (!token) throw new Error("Set CF_TRYNXEON_TOKEN (Zone:Read + DNS:Edit on trynxeon.com). Nothing was contacted.");
  if (!/^[A-Za-z0-9_-]{20,80}$/.test(token)) throw new Error("CF_TRYNXEON_TOKEN has an unexpected shape; refusing to use it.");
  if (!/^(\d{1,3}\.){3}\d{1,3}$/.test(ORIGIN_IP)) throw new Error("WS_ORIGIN_IP is not an IPv4 address.");
  if (setProxied !== undefined && setProxied !== "true" && setProxied !== "false") throw new Error("--set-proxied must be true or false.");

  console.log(`Mode: ${setProxied !== undefined ? `set-proxied=${setProxied}` : "create"}   ${apply ? "APPLY" : "DRY RUN (nothing will be changed)"}`);
  console.log(`Record: ${HOST}  A  ${ORIGIN_IP}  proxied=${setProxied ?? proxied}  ttl=auto\n`);

  if (!(await cfVerifyToken(token))) throw new Error("Cloudflare says the token is not active/valid.");
  const zoneId = await cfFindZoneId(token, ZONE);
  if (!zoneId) throw new Error(`This token cannot see the ${ZONE} zone (wrong account or missing Zone:Read).`);
  console.log(`Zone ${ZONE}: found.`);

  // Read-only: every record (any type) for exactly this host.
  const existing = await cfRequest<Rec[]>(token, "GET", `/zones/${zoneId}/dns_records?name=${encodeURIComponent(HOST)}&per_page=100`);

  if (setProxied !== undefined) {
    const a = existing.filter((r) => r.type === "A");
    if (existing.length !== 1 || a.length !== 1) throw new Error(`Expected exactly one record for ${HOST} (an A); found ${existing.map((r) => r.type).join(",") || "none"}. Refusing.`);
    const r = a[0];
    if (r.name !== HOST || r.content !== ORIGIN_IP) throw new Error(`Existing A record points at ${r.content}, not ${ORIGIN_IP}. Refusing to touch it.`);
    const want = setProxied === "true";
    if (!!r.proxied === want) { console.log(`Already proxied=${want}. Nothing to do.`); return; }
    console.log(`Would change proxied ${!!r.proxied} -> ${want} on ${HOST} only.`);
    if (!apply) return console.log("\nDry run complete. Re-run with --apply.");
    await cfRequest(token, "PUT", `/zones/${zoneId}/dns_records/${r.id}`, { type: "A", name: HOST, content: ORIGIN_IP, proxied: want, ttl: 1, comment: COMMENT });
    console.log(`Done: ${HOST} proxied=${want}.`);
    return;
  }

  if (existing.length > 0) {
    console.log(`\nREFUSING: ${HOST} already has ${existing.length} record(s):`);
    for (const r of existing) console.log(`  ${r.type}  ${r.content}  proxied=${r.proxied}`);
    throw new Error("The host already exists. Nothing was created. Inspect it in the Cloudflare dashboard.");
  }
  console.log(`${HOST}: no existing record of any type. Safe to create.`);
  if (!apply) return console.log("\nDry run complete. Re-run with --apply to create exactly this one A record.");
  const res = await cfRequest<Rec>(token, "POST", `/zones/${zoneId}/dns_records`, { type: "A", name: LABEL, content: ORIGIN_IP, proxied, ttl: 1, comment: COMMENT });
  console.log(`\nCreated ${res.name} A ${res.content} proxied=${res.proxied} (id ${res.id}).`);
}

main().catch((e) => {
  console.error(`\nERROR: ${e instanceof Error ? e.message : String(e)}`);
  process.exit(1);
});
EOF
